function notify(message:string){$('toast').textContent=message;$('toast').hidden=false;toastUntil=performance.now()+4000;}
function globalError(message:string){$('global-error').textContent=message;$('global-error').hidden=false;setTimeout(()=>$('global-error').hidden=true,10000);}
function applySettings(){if(!settings.targetLock)clearTarget();$<HTMLInputElement>('target-assist').checked=settings.targetLock;audio.setVolume(settings.volume);audio.setMuted(settings.muted);audio.setRhythm(settings.rhythm);world?.setQuality(settings.quality);world?.setReducedMotion(settings.reducedMotion);world?.setLightingMode(settings.lighting);document.documentElement.classList.toggle('reduced-motion',settings.reducedMotion);$<HTMLInputElement>('volume').value=String(settings.volume*100);$('volume-value').textContent=`${Math.round(settings.volume*100)}%`;$<HTMLInputElement>('mute').checked=settings.muted;$<HTMLInputElement>('rhythm').checked=settings.rhythm;$<HTMLInputElement>('quality').value=settings.quality;$<HTMLSelectElement>('lighting').value=settings.lighting;$<HTMLInputElement>('sensitivity').value=String(settings.sensitivity*100);$<HTMLInputElement>('reduced-motion').checked=settings.reducedMotion;saveSettings();}
applySettings();
function sendNeutral(){previousInputTime=performance.now();clearTarget();mousePointer=null;dragging=false;held.clear();pointerFire=false;touchFire=false;touchX=0;touchZ=0;connection?.input({type:'input',seq:++seq,moveX:0,moveZ:0,yaw,pitch,fire:false,jump:false});}
function setActive(){world?.setActive(inGame&&!document.hidden&&!activeDialog);const active=inGame&&ready&&!activeDialog&&!document.hidden&&!ended;connection?.pause(!active);audio.setActive(active||(inGame&&ended&&!document.hidden&&performance.now()<endAudioUntil));}
function openDialog(id:string){sendNeutral();if(document.pointerLockElement)document.exitPointerLock();previousFocus=document.activeElement as HTMLElement;if(activeDialog)activeDialog.close();activeDialog=$<HTMLDialogElement>(id);activeDialog.showModal();setActive();}
function closeDialog(){const was=activeDialog;if(was?.id==='hero-dialog'){galleryRequest++;showcase?.destroy();showcase=undefined;}activeDialog=undefined;was?.close();sendNeutral();setActive();if(inGame&&!ended)canvas.focus({preventScroll:true});else previousFocus?.focus({preventScroll:true});}
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('cancel',event=>{event.preventDefault();if(d.id!=='result-dialog')closeDialog();}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeDialog));
function showSettings(){ $('pause-note').textContent=inGame?(isOnline?'Your team match continues while this menu is open.':'Practice pauses while this menu is open.'):'Your preferences are saved on this device.';$('leave-game').hidden=!inGame;$('resume-game').textContent=inGame?'Resume match':'Done';openDialog('pause-dialog');}
$('lobby-settings').onclick=showSettings;$('pause-open').onclick=showSettings;$('resume-game').onclick=closeDialog;
$('controls-button').onclick=()=>openDialog('controls-dialog');
$<HTMLInputElement>('volume').oninput=e=>{settings.volume=Number((e.target as HTMLInputElement).value)/100;applySettings();};
$<HTMLInputElement>('mute').onchange=e=>{settings.muted=(e.target as HTMLInputElement).checked;applySettings();if(!settings.muted)void audio.unlock().catch(()=>$('sound-status').textContent='Sound could not start. Try Preview sound.');};
$<HTMLInputElement>('rhythm').onchange=e=>{settings.rhythm=(e.target as HTMLInputElement).checked;applySettings();};
$<HTMLSelectElement>('quality').onchange=e=>{settings.quality=(e.target as HTMLSelectElement).value as 'high'|'low';applySettings();};
$<HTMLSelectElement>('lighting').onchange=e=>{settings.lighting=(e.target as HTMLSelectElement).value as Settings['lighting'];applySettings();};
$<HTMLInputElement>('sensitivity').oninput=e=>{settings.sensitivity=Number((e.target as HTMLInputElement).value)/100;applySettings();};
$<HTMLInputElement>('reduced-motion').onchange=e=>{settings.reducedMotion=(e.target as HTMLInputElement).checked;applySettings();};
$<HTMLInputElement>('target-assist').onchange=e=>{settings.targetLock=(e.target as HTMLInputElement).checked;applySettings();};
$('sound-preview').onclick=()=>{void audio.preview().then(()=>$('sound-status').textContent=settings.volume===0?'Volume is at zero. Raise it to hear the preview.':'Preview played. Your mute preference is unchanged.').catch(()=>$('sound-status').textContent='Audio is unavailable in this browser.');};
async function showHero(id:string){const serial=++galleryRequest;selectHero(id);$('showcase-name').textContent=selected.name;$('showcase-status').textContent='Preparing the hero…';document.querySelectorAll<HTMLButtonElement>('[data-clip]').forEach(b=>b.disabled=true);try{if(!showcase)showcase=createHeroShowcase($<HTMLCanvasElement>('hero-preview'));await showcase.setHero(id);if(serial!==galleryRequest)return;$('showcase-status').textContent=`${selected.epithet} · Drag to rotate`;document.querySelectorAll<HTMLButtonElement>('[data-clip]').forEach(b=>{b.disabled=false;b.setAttribute('aria-pressed',String(b.dataset.clip==='idle'));});}catch(error){if(serial===galleryRequest)$('showcase-status').textContent=error instanceof Error?error.message:'The model could not load.';}}
