function updateShop(){const actor=self();if(!actor)return;const guide=heroGuideById(actor.heroId)!;$('hero-upgrade-note').textContent=`${heroById(actor.heroId).name} · Power: ${guide.upgrades.power} Vitality: ${guide.upgrades.vitality} Tempo: ${guide.upgrades.tempo}`;const atBase=distance(actor,SPAWNS[actor.team])<=ARENA_RULES.baseRadius;$('shop-status').textContent=actor.health<=0?'Your hero must be alive to use the forge.':atBase?`${actor.credits} credits available · You are at the spawn forge.`:'Return to your spawn to upgrade.';for(const key of ['power','vitality','tempo'] as const){const rank=actor.upgrades[key],cost=UPGRADE_COSTS[key]*(rank+1),button=$<HTMLButtonElement>(`buy-${key}`);button.querySelector('b')!.textContent=rank===MAX_UPGRADE?'MAX':`${cost} ✦ · ${rank}/${MAX_UPGRADE}`;button.disabled=!atBase||rank>=MAX_UPGRADE||actor.credits<cost||actor.health<=0||!ready||[...pending.values()].some(p=>p.upgrade===key);}}
function showResult(){if(!snapshot)return;const actor=self(),won=snapshot.winner===actor?.team;$('result-title').textContent=snapshot.winner==='draw'?'An even confluence':won?'Your team prevails':'A new chance awaits';$('result-reason').textContent=snapshot.reason;$('result-score').textContent=`SUN ${snapshot.scores.sun} : ${snapshot.scores.moon} MOON`;$('scoreboard').innerHTML='<div class="score-row heading"><span>Hero / player</span><span>K / D / A</span><span>Damage</span></div>'+snapshot.actors.filter(a=>a.kind==='hero').map(a=>`<div class="score-row ${a.id===playerId?'you':''}"><span>${esc(heroById(a.heroId).name)} <small>${esc(a.name)}${a.bot?' · BOT':''}</small></span><span>${a.kills} / ${a.deaths} / ${a.assists}</span><span>${Math.round(a.damageDealt)}</span></div>`).join('');openDialog('result-dialog');}
function updateHud(){if(!snapshot)return;const actor=self();if(!actor)return;const h=heroById(actor.heroId),seconds=Math.max(0,Math.ceil(snapshot.duration-snapshot.time));$('match-clock').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;$('team-score').parentElement!.className=`team-score ${actor.team}`;$('enemy-score').parentElement!.className=`team-score ${actor.team==='sun'?'moon':'sun'}`;$('team-score').textContent=String(snapshot.scores[actor.team]);$('enemy-score').textContent=String(snapshot.scores[actor.team==='sun'?'moon':'sun']);$('hero-hudname').textContent=`${h.name} · ${actor.team.toUpperCase()}`;$('health-count').textContent=`${Math.ceil(Math.max(0,actor.health))} / ${actor.maxHealth}`;$('health-bar').style.width=`${Math.max(0,actor.health/actor.maxHealth)*100}%`;$('shield-count').textContent=actor.shield>0?`+${Math.ceil(actor.shield)} shield`:'';$('hero-record').textContent=`${actor.kills} defeats · ${actor.assists} assists · ${actor.deaths} falls`;$('credits').textContent=String(actor.credits);updateWildHud(actor);
 const towers=snapshot.structures.filter(t=>t.team!==actor.team&&t.kind==='tower'&&t.health<=0).length,core=snapshot.structures.find(t=>t.kind==='core'&&t.team!==actor.team);$('objective-copy').textContent=core&&!core.shielded?'Their core is open. Finish the push.':`${towers}/2 rival towers broken · Open their core`;
 for(let i=0;i<3;i++){const b=$<HTMLButtonElement>(`ability-${i}`),cool=actor.cooldowns[i]||0;b.querySelector('.ability-name')!.textContent=h.abilities[i]!.name;b.querySelector('.ability-time')!.textContent=cool>.05?`${Math.ceil(cool)}s`:'READY';b.querySelector<HTMLElement>('i')!.style.height=`${cool/h.abilities[i]!.cooldown*100}%`;b.title=h.abilities[i]!.description;b.setAttribute('aria-label',`${abilityKeys[i]} · ${h.abilities[i]!.name}. ${h.abilities[i]!.description} ${cool>.05?`${Math.ceil(cool)} seconds remaining`:'Ready'}`);b.disabled=!ready||actor.health<=0||!!actor.cast||cool>.05||[...pending.values()].some(p=>p.slot===i);}
 $('cast-progress').hidden=!actor.cast;if(actor.cast){const cast=actor.cast,progress=(snapshot.time-cast.startedAt)/Math.max(.05,cast.endsAt-cast.startedAt);$('cast-name').textContent=h.abilities[cast.slot].name;$('cast-fill').style.width=`${Math.max(0,Math.min(1,progress))*100}%`;$('cast-hint').textContent=cast.phase==='travel'?'Landing at the marked position':`${Math.max(0,cast.releaseAt-snapshot.time).toFixed(1)}s · Hold the opening`;}$('respawn').hidden=actor.health>0;$('respawn').textContent=`Returning in ${Math.ceil(actor.respawn)}s · Your team fights on`;if(activeDialog?.id==='upgrades-dialog')updateShop();drawMap(actor);
}
function updateWildHud(actor:Actor){
 if(!snapshot)return;
 const buffs=([['ward','Ward','Absorbs incoming damage'],['vigor','Vigor','Regenerates health'],['haste','Haste','Faster movement']] as const).filter(([key])=>(actor.effects[key]||0)>0&&(key!=='ward'||actor.shield>0));
 $('buff-status').innerHTML=buffs.map(([key,label,description])=>`<span data-buff="${key}" title="${description}">${label} <b>${Math.ceil(actor.effects[key]||0)}s</b></span>`).join('');
 const camp=JUNGLE_CAMPS.reduce((closest,next)=>distance(actor,next)<distance(actor,closest)?next:closest);
 const guardian=snapshot.neutrals.find(n=>n.campId===camp.id),close=distance(actor,camp)<=16;
 $('camp-status').hidden=!close;
 if(close){const stats=NEUTRAL_STATS[camp.species],state=!guardian||guardian.health<=0?`Returns in ${Math.max(0,Math.ceil((guardian?.respawnAt??JUNGLE_RULES.firstSpawn)-snapshot.time))}s`:guardian.state==='returning'?'Returning · no reward':`${Math.ceil(guardian.health)} HP · ${stats.buff}`;const copy=`${camp.name} · ${state}`;if($('camp-status').textContent!==copy)$('camp-status').textContent=copy;}
}
function drawMap(actor:Actor){if(!snapshot)return;const map=$<HTMLCanvasElement>('map'),ctx=map.getContext('2d');if(!ctx)return;const x=(v:number)=>85+v*1.12,z=(v:number)=>100+v*1.12;ctx.clearRect(0,0,170,200);ctx.fillStyle='#071b22e8';ctx.fillRect(0,0,170,200);ctx.strokeStyle='#a68d5d55';ctx.lineWidth=5;for(const lane of [-40,0,40]){ctx.beginPath();ctx.moveTo(x(0),z(-69));ctx.lineTo(x(lane),z(-45));ctx.lineTo(x(lane),z(45));ctx.lineTo(x(0),z(69));ctx.stroke();}ctx.fillStyle='#95b7ad33';for(const s of SOLIDS)ctx.fillRect(x(s.x-s.w/2),z(s.z-s.d/2),s.w*1.12,s.d*1.12);for(const s of snapshot.structures){if(s.health<=0)continue;ctx.fillStyle=s.team==='sun'?'#f1cb7a':'#8cd7ef';ctx.fillRect(x(s.x)-4,z(s.z)-4,8,8);if(s.shielded){ctx.strokeStyle='#fff';ctx.strokeRect(x(s.x)-5,z(s.z)-5,10,10);}}for(const camp of JUNGLE_CAMPS){const neutral=snapshot.neutrals.find(n=>n.campId===camp.id);ctx.strokeStyle=neutral&&neutral.health>0?'#c8f2ce':'#6e8d8a';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x(camp.x),z(camp.z)-4);ctx.lineTo(x(camp.x)+4,z(camp.z));ctx.lineTo(x(camp.x),z(camp.z)+4);ctx.lineTo(x(camp.x)-4,z(camp.z));ctx.closePath();ctx.stroke();if(neutral?.state==='aggro'){ctx.fillStyle='#e8ba92';ctx.fill();}}for(const shard of snapshot.goldShards){ctx.fillStyle='#ffe28e';ctx.fillRect(x(shard.x)-1.2,z(shard.z)-1.2,2.4,2.4);}for(const a of snapshot.actors){if(a.health<=0)continue;ctx.fillStyle=a.id===playerId?'#fff':a.team==='sun'?'#e6be6b':'#86cde8';const r=a.kind==='hero'?3:1.4;ctx.beginPath();if(a.team!==actor.team){ctx.moveTo(x(a.x),z(a.z)-r-1);ctx.lineTo(x(a.x)+r+1,z(a.z));ctx.lineTo(x(a.x),z(a.z)+r+1);ctx.lineTo(x(a.x)-r-1,z(a.z));ctx.closePath();}else ctx.arc(x(a.x),z(a.z),r,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#fff';ctx.beginPath();ctx.moveTo(x(actor.x),z(actor.z));ctx.lineTo(x(actor.x+Math.sin(yaw)*7),z(actor.z+Math.cos(yaw)*7));ctx.stroke();}

function clearTarget(){aimTarget=null;$('target-label').hidden=true;$('target-lock').setAttribute('aria-pressed','false');}
function toggleTarget(){
 if(!inGame||!ready||activeDialog||ended||!snapshot)return;
 if(!settings.targetLock){notify('Enable target lock in Settings to use it.');return;}
 if(aimTarget){clearTarget();return;}
 aimTarget=acquireTarget(snapshot,playerId,yaw,pitch);previousInputTime=performance.now();
 $('target-lock').setAttribute('aria-pressed',String(!!aimTarget));
 if(!aimTarget)notify('Aim near a visible rival or guardian within 32 metres, then lock.');
}
$('target-lock').onclick=toggleTarget;
function advanceAim(dt:number){
 yaw+=(Number(held.has('KeyJ'))-Number(held.has('KeyL')))*dt*1.6;
 pitch=Math.max(-.75,Math.min(.75,pitch+(Number(held.has('KeyI'))-Number(held.has('KeyK')))*dt*1.3));
 if(!aimTarget||!snapshot||!world)return;
 if(!ready||activeDialog||ended||document.hidden){clearTarget();return;}
 const target=targetAim(snapshot,playerId,aimTarget);
 if(!target){clearTarget();return;}
 if(!self()?.cast){const delta=Math.atan2(Math.sin(target.yaw-yaw),Math.cos(target.yaw-yaw));const step=1.8*dt;yaw+=Math.max(-step,Math.min(step,delta));pitch=Math.max(-.75,Math.min(.75,pitch+Math.max(-step,Math.min(step,target.pitch-pitch))));}
}
function renderTargetLabel(){
 if(!aimTarget||!snapshot||!world)return;
 const target=targetAim(snapshot,playerId,aimTarget);if(!target){clearTarget();return;}
 const screen=world.project({x:target.x,y:target.y+1,z:target.z});
 $('target-label').hidden=!screen.visible;$('target-label').textContent=`Locked · ${target.label}`;$('target-label').style.left=`${screen.x}px`;$('target-label').style.top=`${screen.y}px`;
}

const keyActions:Record<string,0|1|2>={KeyQ:0,KeyE:1,KeyR:2};
window.addEventListener('keydown',e=>{if(!inGame)return;if(loading){if(e.code==='Escape'){e.preventDefault();leaveMatch();}return;}if(e.code==='Escape'){e.preventDefault();if(activeDialog){if(activeDialog.id!=='result-dialog')closeDialog();}else showSettings();return;}if(activeDialog||ended||e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;if((e.code==='Space'||e.code==='Enter')&&e.target instanceof Element&&e.target.closest('button,summary'))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyI','KeyJ','KeyK','KeyL','KeyF','Space','KeyQ','KeyE','KeyR','KeyB','KeyT'].includes(e.code))e.preventDefault();held.add(e.code);if(['KeyI','KeyJ','KeyK','KeyL'].includes(e.code)){clearTarget();if(!e.repeat)previousInputTime=performance.now();}if(!e.repeat&&e.code==='KeyT')toggleTarget();if(!e.repeat&&e.code in keyActions)command({action:'ability',slot:keyActions[e.code]!});if(!e.repeat&&e.code==='KeyB'){updateShop();openDialog('upgrades-dialog');}});
window.addEventListener('keyup',e=>held.delete(e.code));
window.addEventListener('blur',()=>{sendNeutral();if(inGame&&!activeDialog&&!ended)showSettings();});
document.addEventListener('visibilitychange',()=>{sendNeutral();if(document.hidden&&inGame&&!activeDialog&&!ended)showSettings();setActive();});
// Pointer events report only the first/last mouse button in a chord. Mouse events
// report each transition; a real mouse pointer guard excludes touch compatibility events.
canvas.addEventListener('pointerdown',e=>{if(!inGame||activeDialog||ended||e.pointerType!=='mouse')return;canvas.focus();mousePointer=e.pointerId;if(document.pointerLockElement!==canvas)canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('mousedown',e=>{if(mousePointer===null||!inGame||activeDialog||ended)return;if(e.button===2){e.preventDefault();toggleTarget();return;}if(e.button!==0)return;pointerFire=true;dragging=true;lastPointerX=e.clientX;lastPointerY=e.clientY;if(!document.pointerLockElement&&canvas.requestPointerLock)try{const request=canvas.requestPointerLock();if(request&&'catch' in request)void request.catch(()=>{});}catch{/* Drag aiming stays available. */}});
window.addEventListener('mouseup',e=>{if(e.button===0){dragging=false;pointerFire=false;}});
function aim(dx:number,dy:number){if(dx||dy)clearTarget();yaw-=dx*.0025*settings.sensitivity;pitch=Math.max(-.75,Math.min(.75,pitch-dy*.0025*settings.sensitivity));}
window.addEventListener('pointermove',e=>{if(!inGame||activeDialog||ended)return;if(document.pointerLockElement===canvas)aim(e.movementX,e.movementY);else if(dragging&&e.pointerType!=='touch'){aim(e.clientX-lastPointerX,e.clientY-lastPointerY);lastPointerX=e.clientX;lastPointerY=e.clientY;}});
window.addEventListener('pointerup',e=>{if(e.pointerId===mousePointer){mousePointer=null;dragging=false;pointerFire=false;}});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointercancel',()=>{mousePointer=null;dragging=false;pointerFire=false;});
canvas.addEventListener('lostpointercapture',()=>{if(document.pointerLockElement!==canvas){mousePointer=null;dragging=false;pointerFire=false;}});
function touchControl(id:string,move:(e:PointerEvent,start:{x:number;y:number})=>void,end:()=>void){const element=$(id);let start:{x:number;y:number}|undefined;let pointer=-1;element.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;start={x:e.clientX,y:e.clientY};element.setPointerCapture(e.pointerId);move(e,start);});element.addEventListener('pointermove',e=>{if(start&&e.pointerId===pointer)move(e,start);});for(const type of ['pointerup','pointercancel','lostpointercapture'])element.addEventListener(type,()=>{start=undefined;end();});}
touchControl('touch-pad',(e,start)=>{touchX=Math.max(-1,Math.min(1,(e.clientX-start.x)/38));touchZ=Math.max(-1,Math.min(1,(start.y-e.clientY)/38));$('touch-pad').querySelector<HTMLElement>('i')!.style.transform=`translate(${touchX*28}px,${-touchZ*28}px)`;},()=>{touchX=0;touchZ=0;$('touch-pad').querySelector<HTMLElement>('i')!.style.transform='';});
let lookLast:{x:number;y:number}|undefined;
touchControl('touch-look',(e,start)=>{if(!lookLast)lookLast=start;aim(e.clientX-lookLast.x,e.clientY-lookLast.y);lookLast={x:e.clientX,y:e.clientY};},()=>lookLast=undefined);
touchControl('shoot',()=>touchFire=true,()=>touchFire=false);touchControl('jump',()=>held.add('Space'),()=>held.delete('Space'));
// Aim follows elapsed input time, independently of the renderer's frame cap.
setInterval(()=>{const inputNow=performance.now(),inputDt=Math.max(0,Math.min(.25,(inputNow-previousInputTime)/1000));previousInputTime=inputNow;if(!inGame||!ready||activeDialog||ended||document.hidden)return;advanceAim(inputDt);let sideways=Number(held.has('KeyD')||held.has('ArrowRight'))-Number(held.has('KeyA')||held.has('ArrowLeft'))+touchX;let forward=Number(held.has('KeyW')||held.has('ArrowUp'))-Number(held.has('KeyS')||held.has('ArrowDown'))+touchZ;const len=Math.hypot(sideways,forward);if(len>1){sideways/=len;forward/=len;}const input:ArenaInput={type:'input',seq:++seq,moveX:-Math.cos(yaw)*sideways+Math.sin(yaw)*forward,moveZ:Math.sin(yaw)*sideways+Math.cos(yaw)*forward,yaw,pitch,fire:pointerFire||touchFire||held.has('KeyF'),jump:held.has('Space')};connection?.input(input);for(const [id,p]of pending)if(performance.now()-p.at>4000){pending.delete(id);notify('Action confirmation timed out. Check your connection.');}},50);
let previousFrame=performance.now();
function frame(now:number){const raw=(now-previousFrame)/1000,dt=Math.min(.1,raw);previousFrame=now;if(inGame&&world&&snapshot&&!activeDialog&&!document.hidden){world.setCamera(yaw,pitch);world.update(snapshot,playerId,dt);renderTargetLabel();const reticle=world.reticle();$('reticle').hidden=!reticle?.visible||!!activeDialog||ended;if(reticle){$('reticle').style.left=`${reticle.x}px`;$('reticle').style.top=`${reticle.y}px`;}frames++;frameTotal+=raw;frameMax=Math.max(frameMax,raw);if(now-lastHud>150){lastHud=now;updateHud();}if(now>toastUntil)$('toast').hidden=true;if(now>goldFeedbackUntil)$('gold-feedback').hidden=true;$('reticle').classList.toggle('hit',now<hitUntil);$('hud').classList.toggle('hurt',now<hurtUntil);}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
if(import.meta.env.DEV){Object.defineProperty(window,'__YUGA',{value:Object.freeze({snapshot:()=>snapshot?structuredClone(snapshot):undefined,playerId:()=>playerId,metrics:()=>({frames,meanFps:frames/Math.max(.001,frameTotal),maxFrameMs:frameMax*1000,pendingActions:pending.size,ready,room,isOnline,yaw,pitch,targetId:aimTarget}),audio:()=>({...audio.diagnostics}),assets:()=>world?.assetDiagnostics(),showcase:()=>showcase?.diagnostics()}),writable:false});}
window.addEventListener('pagehide',event=>{sendNeutral();if(event.persisted){leaveMatch();return;}connection?.close();showcase?.destroy();audio.destroy();world?.destroy();});
